      SUBROUTINE PARSET      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'FLUSHC.CIN'C----------------------------------------------------------------------------      INTEGER       TYPEN      LOGICAL       INSPECC      NITER = 1      NNOTO = -1CC     MARK ALGEBRAIC OPERATIONS NOT DONEC      DO 20 NN = 1, NEL      II = ISTOR(NN)      TYPE = IDATA(II)      IF (TYPE .EQ. 23) TIE(II+3) = 1   20 CONTINUECC     RUN THROUGH BEAM LINE PERFORMING ALGEBRAIC OPERATIONSC   50 NUM = 1      NBEG = 0      NNOT = 0      NNOTS = 0      INSPEC = .TRUE.C   70 I = ISTOR(NUM)      TYPE = IDATA(I)C      IF (TYPE .EQ. 23) GO TO 2300      GO TO 6100CC     23. -- ALGEBRAIC OPERATIONC 2300 K1TIE = TIE(I+1)      K2TIE = TIE(I+2)      JTIE = TIE(I+4)      K1REG = IDATA(I+1)      K2REG = IDATA(I+2)      IOPN = IDATA(I+3)      JREG = IDATA(I+4)      IF (INSPEC) THEN        IF (NBEG .EQ. 0) NBEG = NUM        IF (K1TIE .EQ. 100) THEN          IPAR = K1REG 2310     IF (TIE(IPAR) .EQ. 100) THEN            IPAR = IDATA(IPAR)            GO TO 2310          ENDIF          IF (TIE(IPAR) .EQ. 99) THEN            ISET = IPAR - 3            IF (TIE(ISET) .EQ. 1) NNOT = NNOT + 1          ENDIF        ENDIF        IF (IOPN .LT. 10) THEN          IF (K2TIE .EQ. 100) THEN            IPAR = K2REG 2320       IF (TIE(IPAR) .EQ. 100) THEN              IPAR = IDATA(IPAR)              GO TO 2320            ENDIF            IF (TIE(IPAR) .EQ. 99) THEN              ISET = IPAR - 3              IF (TIE(ISET) .EQ. 1) NNOT = NNOT + 1            ENDIF          ENDIF        ENDIF      ELSE        CALL COMBIN        TIE(I+3) = 0      ENDIF      IF (JTIE .EQ. 100) THEN        IF (INSPEC) THEN          TYPEN = IDATA(ISTOR(NUM+2))          HELEM = .FALSE.          IF (TYPEN .EQ. 10 .OR. TYPEN .EQ. 33 .OR. TYPEN .EQ. 38     1        .OR. TYPEN .EQ. 50 .OR. TYPEN .EQ. 51 .OR. TYPEN .EQ. 52)     2        HELEM = .TRUE.          IF (NNOT .EQ. 0 .AND. .NOT. HELEM) THEN            NUM = NBEG - 1            INSPEC = .FALSE.          ELSE            IF (.NOT. HELEM) NNOTS = NNOTS + NNOT            NNOT = 0            NBEG = 0          ENDIF        ELSE          NBEG = 0          NNOTS = NNOTS + NNOT          NNOT = 0             INSPEC = .TRUE.         ENDIF      ENDIFCC     ADVANCE TO NEXT ELEMENTC 6100 NUM = NUM + 1      IF (NUM .LE. NEL) GO TO 70C      IF (NITER .GE. 10) GO TO 6200      NITER = NITER + 1      IF (NNOTS .GT. 0) THEN        IF (NNOTO .EQ. NNOTS) FLUSHL = .TRUE.        IF (NNOTO .NE. NNOTS) THEN          NNOTO = NNOTS          GO TO 50        ENDIF      ENDIFCC     UNMARK ALGEBRAIC OPERATIONS FOR CONSTRAINTS, ETC.C 6200 DO 6220 NN = 1, NEL      II = ISTOR(NN)      TYPE = IDATA(II)      IF (TYPE .EQ. 23) TIE(II+3) = 0 6220 CONTINUE      RETURN      END